import{z as i,x as n,o as s,c as m,q as t,j as o,D as e,d as E,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"WebAssembly 作目标","description":"","frontmatter":{"title":"WebAssembly 作目标","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wasm-target.md","filePath":"cs/wasm-target.md","lastUpdated":1791413859000}'),B={name:"cs/wasm-target.md"};function d(p,a,c,_,h,T){const r=n("Mermaid");return s(),m("div",null,[a[2]||(a[2]=t('<h1 id="webassembly-作目标" tabindex="-1">WebAssembly 作目标 <a class="header-anchor" href="#webassembly-作目标" aria-label="Permalink to &quot;WebAssembly 作目标&quot;">​</a></h1><div class="epigraph"><p>Wasm 是带验证的栈式虚拟 ISA：线性内存、结构化控制流、可移植。编译器可把它当后端，而不是只当浏览器插件。</p><footer>—— 据 Haas et al., Bringing the Web up to Speed with WebAssembly；Wasm 规范；对照[字节码](/cs/bytecode-interpreter) 与 ELF 整理</footer></div><p>上一课<a href="/cs/language-memory-model">内存模型</a> 是共享内存线程。Wasm 默认线性内存+可选线程扩展。缺口是<strong>当编译目标</strong>：lowering、wasm-ld、与 JS 宿主。MLIR 下一课。不重写 Transformer，不写前端框架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ELF 绑 OS ABI。Wasm：验证保证类型化栈、无跳进指令中间。控制流用 block/loop/br，利于验证，指令选择要改写任意 CFG（或用 <code>relooper</code>/异常扩展）。缺口是<strong>这一 ABI</strong>，不是 JMM 全文。</p><p>线性内存：一块数组，指针是索引。GC 提案与 reference types 在演进，点名。</p><h3 id="wasm-不是-java-字节码" tabindex="-1">Wasm 不是 Java 字节码 <a class="header-anchor" href="#wasm-不是-java-字节码" aria-label="Permalink to &quot;Wasm 不是 Java 字节码&quot;">​</a></h3><p>无内置对象模型、无内置 GC（直到提案）。更接近便携机器码。不要当 JVM 替代品讲类库。</p><p><span class="marginnote">Haas et al. 2017。Wasm Core Spec。LLVM wasm 后端。本课目标描述视角。</span></p><p><span class="marginnote">「线性内存」翻译成大白话：一块连续的大数组，所谓指针只是数组下标。模块伪造不出越出数组的地址——越界在引擎里被一刀切成就地陷阱，这正是沙箱安全性的根基。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LLVM：<code>--target=wasm32-unknown-unknown</code> 或 <code>wasi</code>。lowering：i32/i64、内存 intrinsic、调用 <code>call_indirect</code> 表。链接：<code>wasm-ld</code> 合成模块。WASI：系统调用像精简 OS。</p>',12)),(s(),o(A,null,{default:e(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22LLVM%20IR%22%5D%20--%3E%20WASM%5B%22Wasm%20%E6%A8%A1%E5%9D%97%22%5D%0A%20%20WASM%20--%3E%20VAL%5B%22%E9%AA%8C%E8%AF%81%22%5D%0A%20%20VAL%20--%3E%20ENG%5B%22%E5%BC%95%E6%93%8E%20JIT%20%2F%20%E8%A7%A3%E9%87%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">数字实例：wasm32 下指针是 32 位索引，最多指到 4 GiB 线性内存；内存按页增长，页粒度 64 KiB——<code>memory.grow</code> 一次至少扩 65536 字节。</span></p><p>与<a href="/cs/cross-compile-triple">交叉三元组</a>：<code>wasm32-wasi</code> 是三元组。与栈式 VM 课对照编码。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>引擎（V8、Wasmtime）再 JIT 到 native。陷阱：越界内存。线程：共享内存+原子，模型接近 C++。不要假设可随意 <code>mmap</code> 可执行——沙箱。</p>',4)),(s(),o(A,null,{default:e(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20BYTES%5B%22Wasm%20%E5%AD%97%E8%8A%82%E7%A0%81%E5%88%B0%E8%BE%BE%E5%BC%95%E6%93%8E%22%5D%20--%3E%20V2%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E9%80%90%E6%8C%87%E4%BB%A4%E6%9F%A5%E6%A0%88%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20V2%20--%3E%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E7%BC%96%E8%AF%91%E5%85%88%E8%B7%91%E8%B5%B7%E6%9D%A5%22%5D%0A%20%20BASE%20--%3E%20HOT%5B%22%E7%83%AD%E5%87%BD%E6%95%B0%E4%BA%A4%E7%BB%99%E4%BC%98%E5%8C%96%20JIT%22%5D%0A%20%20HOT%20--%3E%20NAT%5B%22%E6%89%A7%E8%A1%8C%20native%20%E4%BB%A3%E7%A0%81%22%5D%0A%20%20NAT%20--%3E%20T%7B%22%E8%AE%BF%E9%97%AE%E8%B6%8A%E5%87%BA%E7%BA%BF%E6%80%A7%E5%86%85%E5%AD%98%E5%90%97%3F%22%7D%0A%20%20T%20--%20%E6%98%AF%20--%3E%20TRAP%5B%22%E5%B0%B1%E5%9C%B0%E9%99%B7%E9%98%B1%3A%20%E4%BA%A4%E7%BB%99%E5%AE%BF%E4%B8%BB%E5%A4%84%E7%90%86%22%5D%0A%20%20T%20--%20%E5%90%A6%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%2C%20%E7%BB%93%E6%9E%9C%E5%9B%9E%E5%A1%AB%E8%B0%83%E7%94%A8%E6%A0%88%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：把 Wasm 当成「浏览器里的 Java」。它没有内置对象模型与 GC（直到提案落地），也没有标准类库，本质上更接近一段便携机器码；WASI 补齐的才是类 libc 的系统能力。</span></p><p>异常与 DWARF：工具链可嵌调试信息；展开另套。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 MLIR。后课默认：可移植沙箱目标是 Wasm。下一课 MLIR 多层 IR。</p><p>也不把 Wasm 当汇编挖矿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Wasm：可验证的便携 ISA，作后端目标。</li><li>线性内存+结构化控制；宿主提供 WASI 或 JS。</li><li>引擎再 JIT；与 ELF 加载路径不同。</li><li>出处：Haas et al.；Wasm 规范；对照 LLVM 后端。</li></ul>',7))])}const S=i(B,[["render",d]]);export{u as __pageData,S as default};
